    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Select the solution with the highest trade-off sensitivity (most unbalanced objectives)
    selected_idx = 0
    max_trade_off = -float('inf')
    for i, (sol, obj) in enumerate(archive):
        obj1, obj2 = obj
        if obj1 + obj2 == 0:
            continue
        trade_off = abs(obj1 - obj2) / (obj1 + obj2)
        if trade_off > max_trade_off:
            max_trade_off = trade_off
            selected_idx = i

    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst[new_solution == 1])

    # Calculate trade-off sensitivity for each item
    obj1_total, obj2_total = archive[selected_idx][1]
    if obj1_total + obj2_total == 0:
        trade_off_ratio = np.ones_like(value1_lst)
    else:
        trade_off_ratio = (value1_lst / (value2_lst + 1e-6)) * (obj2_total / (obj1_total + 1e-6))

    # Dynamic insertion-removal operator
    items = np.arange(len(base_solution))
    np.random.shuffle(items)

    for item in items:
        if new_solution[item] == 1:
            # Consider removing item if it's low impact and trade-off could be improved
            if (value1_lst[item] + value2_lst[item]) < (obj1_total + obj2_total) * 0.1:
                new_weight = current_weight - weight_lst[item]
                if new_weight <= capacity:
                    new_solution[item] = 0
                    current_weight = new_weight
        else:
            # Consider adding item if it improves trade-off and fits capacity
            if trade_off_ratio[item] > 1.2 or (np.random.random() < 0.4 and trade_off_ratio[item] > 0.8):
                new_weight = current_weight + weight_lst[item]
                if new_weight <= capacity:
                    new_solution[item] = 1
                    current_weight = new_weight

    # Additional diversification step with dynamic criteria
    if np.random.random() < 0.3:
        # Flip items based on their trade-off sensitivity and current solution's trade-off
        flip_candidates = []
        for item in items:
            if new_solution[item] == 1 and trade_off_ratio[item] < 0.7:
                flip_candidates.append(item)
            elif new_solution[item] == 0 and trade_off_ratio[item] > 1.3:
                flip_candidates.append(item)

        if flip_candidates:
            flip_item = np.random.choice(flip_candidates)
            if new_solution[flip_item] == 1:
                if current_weight - weight_lst[flip_item] <= capacity:
                    new_solution[flip_item] = 0
                    current_weight -= weight_lst[flip_item]
            else:
                if current_weight + weight_lst[flip_item] <= capacity:
                    new_solution[flip_item] = 1
                    current_weight += weight_lst[flip_item]

    return new_solution

