    alignment_scores = np.zeros(len(weight_lst))
    for i in range(len(weight_lst)):
        if new_solution[i] == 1:
            alignment_scores[i] = (value1_lst[i] / (obj1_total + 1e-6)) * (value2_lst[i] / (obj2_total + 1e-6))
        else:
            if current_weight + weight_lst[i] <= capacity:
                potential_obj1 = obj1_total + value1_lst[i]
                potential_obj2 = obj2_total + value2_lst[i]
                alignment_scores[i] = (value1_lst[i] / (potential_obj1 + 1e-6)) * (value2_lst[i] / (potential_obj2 + 1e-6))

    # Calculate neighborhood sensitivity
    sensitivity_scores = np.zeros(len(weight_lst))
